Here's a simple function that takes markdown formatted text and converts it into HTML. For the conversion, we'll use the'std::regex' library to replace markdown syntax with HTML tags.

```cpp
#include <iostream>
#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdownText) {
    // Convert markdown headings to HTML headings
    std::regex headingPattern("^#{1,6} (.*)$", std::regex_constants::multiline);
    std::string htmlText = std::regex_replace(markdownText, headingPattern, "<h$1>$2</h$1>");

    // Convert bold text to HTML bold
    std::regex boldPattern("\\*([^\\*]+)\\*");
    htmlText = std::regex_replace(htmlText, boldPattern, "<b>$1</b>");

    // Convert italic text to HTML italic
    std::regex italicPattern("\\*([^\\*]+)");
    htmlText = std::regex_replace(htmlText, italicPattern, "<i>$1</i>");

    // Convert strikethrough text to HTML strikethrough
    std::regex strikethroughPattern("~~([^~]+)~~");
    htmlText = std::regex

